// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.eclipse.rdf4j.sail.lmdb.frontier.SyntheticQuadSnapshot.predicate;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The Fast-AGMS join estimator is the mapped fallback for predicate-only joins once a delete-bearing delta disables the
 * witness and center paths. Its signed lane dot products are noise-dominated when both sides carry large, disjoint key
 * masses: lanes clamp to zero, and the old interval {@code [0, 4 * max(point, laneUpper) + 1]} with confidence 0.86
 * excluded every positive true size. A reported interval must be a bound derived from the sketch's own error, and a
 * zero point is not evidence of an empty join.
 */
class FrontierFastAgmsIntervalTest {

	private static final int PAIRS = 16;
	private static final long UNRELATED_PREDICATE = 9L;

	@Test
	void noiseDominatedFastAgmsNeverClaimsAZeroOrAnIntervalThatExcludesTheExactJoin(@TempDir Path directory)
			throws Exception {
		assertFastAgmsIntervals(directory, 20, 200, 10);
	}

	@Test
	void emptyJoinBetweenHeavyDisjointPredicatesIsATypedUnknownRatherThanACertainZero(@TempDir Path directory)
			throws Exception {
		assertFastAgmsIntervals(directory, 20, 200, 0);
	}

	@Test
	void dominantSharedKeyStaysCoveredAndAccurate(@TempDir Path directory) throws Exception {
		assertFastAgmsIntervals(directory, 4, 50, 400);
	}

	private static void assertFastAgmsIntervals(Path directory, int disjointKeys, int disjointDegree,
			int sharedDegree) throws Exception {
		ArrayList<long[]> rows = new ArrayList<>();
		long nextSubject = 10_000_000L;
		long nextObject = 50_000_000L;
		for (int pair = 0; pair < PAIRS; pair++) {
			long left = 100L + 2L * pair;
			long right = left + 1L;
			for (int key = 0; key < disjointKeys; key++) {
				long leftKey = 90_000_000L + pair * 1_000L + key;
				long rightKey = 91_000_000L + pair * 1_000L + key;
				for (int degree = 0; degree < disjointDegree; degree++) {
					rows.add(new long[] { nextSubject++, left, leftKey, 0L });
					rows.add(new long[] { rightKey, right, nextObject++, 0L });
				}
			}
			long shared = 92_000_000L + pair;
			for (int degree = 0; degree < sharedDegree; degree++) {
				rows.add(new long[] { nextSubject++, left, shared, 0L });
				rows.add(new long[] { shared, right, nextObject++, 0L });
			}
		}
		rows.add(new long[] { 1L, UNRELATED_PREDICATE, 2L, 0L });
		rows.add(new long[] { 3L, UNRELATED_PREDICATE, 4L, 0L });
		SyntheticQuadSnapshot snapshot = new SyntheticQuadSnapshot(92L, rows);
		FrontierStatisticsBuildConfig config = FrontierStatisticsBuildConfig.testing(
				64L * 1024L * 1024L, 64, 256, 256, 2L * 1024L * 1024L);
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(
				256L * 1024L * 1024L, 32L * 1024L * 1024L, 64L * 1024L * 1024L, 32L * 1024L * 1024L);
		try (LmdbStatisticsService service = SyntheticQuadSnapshot.buildService(directory, snapshot, config)) {
			// A delete-bearing delta on an unrelated predicate routes predicate-only joins to Fast-AGMS.
			FrontierStatisticsManifest base = service.currentManifest().orElseThrow();
			service.publish(FrontierStatisticsDeltaBuilder.build(directory, base, List.of(
					new FrontierMutation(93L, 93L, false, true, 1L, UNRELATED_PREDICATE, 2L, 0L)), governor, config));
			long epoch = 93L;

			int agms = 0;
			int unknown = 0;
			int violations = 0;
			StringBuilder report = new StringBuilder();
			for (int pair = 0; pair < PAIRS; pair++) {
				long left = 100L + 2L * pair;
				long right = left + 1L;
				long exact = snapshot.exactPredicateJoin(left, 2, right, 0);
				FrontierJoinEstimate estimate = service.estimateJoin(epoch, new FrontierJoinProbe(
						predicate(left, FrontierLeafProbe.EXPLICIT), 2, predicate(right, FrontierLeafProbe.EXPLICIT),
						0));
				report.append("\n  pair=").append(pair).append(" exact=").append(exact).append(' ').append(estimate);
				if (estimate.fallbackReason() != FrontierFallbackReason.NONE) {
					unknown++;
					continue;
				}
				if ("frontier-v2-fast-agms".equals(estimate.source())) {
					agms++;
				}
				boolean zeroClaim = estimate.pointRows() <= 0.0d;
				boolean excluded = exact < estimate.lowerRows() || exact > estimate.upperRows();
				// An interval an order of magnitude wider than its point cannot also claim to be a confident answer.
				boolean overconfident = estimate.upperRows() > 10.0d * estimate.pointRows()
						&& estimate.confidence() >= 0.5d;
				if (zeroClaim || excluded || overconfident) {
					violations++;
					report.append(zeroClaim ? "  <- ZERO POINT" : "")
							.append(excluded ? "  <- EXCLUDES EXACT" : "")
							.append(overconfident ? "  <- OVERCONFIDENT" : "");
				}
			}
			assertTrue(agms + unknown == PAIRS,
					"every predicate-only join must be answered by Fast-AGMS or declined: " + report);
			assertTrue(violations == 0,
					"a Fast-AGMS answer must carry a positive point, an interval that contains the exact join and a "
							+ "confidence that reflects its width; "
							+ "violations=" + violations + ", fastAgms=" + agms + ", unknown=" + unknown + report);
			if (sharedDegree > 0 && disjointKeys * disjointDegree < sharedDegree * sharedDegree) {
				assertTrue(agms == PAIRS, "a signal-dominated join must stay answered: " + report);
			}
		}
	}
}
